contract InvMutTest {
    C c;
    uint public callCount;
    mapping(address => uint) public received;
    mapping(address => address) public sentFrom;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint v, uint dec) public {
        require(tos.length > 0);
        require(dec <= 18);
        require(v < 10 ** 18);
        bool ok;
        ok = c.transfer(from, address(this), tos, v, dec);
        bool allOk = ok && callCount == tos.length;
        for (uint i = 0; i < tos.length; i++) {
            allOk = allOk && received[tos[i]] == v * 10 ** dec && sentFrom[tos[i]] == from;
        }
        assert(allOk);
    }

    fallback() external payable {
        bytes4 sel = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (bytes4(msg.data) == sel) {
            (address f, address t, uint val) = abi.decode(msg.data[4:], (address, address, uint256));
            callCount = callCount + 1;
            received[t] = val;
            sentFrom[t] = f;
        }
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    receive() external payable {}
}

